import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class JsonReader_nextInt_TriageGen1Test {

    @Test
    public void testNextInt_FromLongPeeked() throws IOException {
        // Simulates the case where peeked is PEEKED_LONG
        // Since we cannot easily mock the internal state of JsonReader without reflection,
        // we use a JSON input that triggers the various branches.
        // Note: To specifically hit the 'p == PEEKED_LONG' branch, one would typically 
        // need to use reflection to set the private 'peeked' field.
        // However, providing standard JSON inputs covers the logic branches.

        String json = "123";
        JsonReader reader = new JsonReader(new StringReader(json));
        assertEquals(123, reader.nextInt());
    }
















}

