package com.google.gson.stream;

import com.google.gson.internal.JsonReaderInternalAccess;
import com.google.gson.internal.bind.JsonTreeReader;
import java.io.*;
import java.io.Closeable;
import java.io.EOFException;
import java.io.IOException;
import java.io.Reader;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class JsonReader_nextInt_TriageGen1Test {

















    @Test
    public void testNextInt_SequentialCalls() throws IOException {
        // Ensures peeked = PEEKED_NONE and pos updates work correctly
        String json = "1 2";
        JsonReader reader = new JsonReader(new StringReader(json));
        // Note: JsonReader expects valid JSON structure, so we use a comma
        String jsonValid = "1,2";
        JsonReader reader2 = new JsonReader(new StringReader(jsonValid));
        assertEquals(1, reader2.nextInt());
        assertEquals(2, reader2.nextInt());
    }
}
